public record CreateOrderCommand(UUID orderId, String customerId, List<OrderItemDto> items) {}

public record OrderDetailsQuery(UUID orderId) {}

@Component
public class OrderCommandHandler {
    private final OrderRepository orderRepository;
    private final ApplicationEventPublisher eventPublisher;

    public OrderCommandHandler(OrderRepository orderRepository, ApplicationEventPublisher eventPublisher) {
        this.orderRepository = orderRepository;
        this.eventPublisher = eventPublisher;
    }

    @Transactional
    public void handle(CreateOrderCommand command) {
        Order order = Order.create(command.orderId(), command.customerId(), command.items());
        orderRepository.save(order);
        eventPublisher.publishEvent(new OrderCreatedEvent(order.getId(), order.getCustomerId(), order.getTotal()));
    }
}

@Component
public class OrderQueryHandler {
    private final JdbcTemplate jdbcTemplate;

    public OrderQueryHandler(JdbcTemplate jdbcTemplate) {
        this.jdbcTemplate = jdbcTemplate;
    }

    public OrderDetailsDto handle(OrderDetailsQuery query) {
        String sql = "SELECT order_id, customer_id, total_amount, status FROM read_order_view WHERE order_id = ?";
        return jdbcTemplate.queryForObject(sql, new OrderRowMapper(), query.orderId());
    }
}
